// 使用类实现队列数据结构
class Queue {
    constructor() {
        this.items = [];
    }

    enqueue(item) {
        this.items.push(item);
    }

    dequeue() {
        if (!this.isEmpty()) {
            return this.items.shift();
        }
        return null;
    }

    front() {
        if (!this.isEmpty()) {
            return this.items[0];
        }
        return null;
    }

    isEmpty() {
        return this.items.length === 0;
    }

    size() {
        return this.items.length;
    }
}

// 测试队列操作
const queue = new Queue();
queue.enqueue("客户A");
queue.enqueue("客户B");
queue.enqueue("客户C");
console.log(`队首: ${queue.front()}`);
console.log(`服务: ${queue.dequeue()}`);
console.log(`队列大小: ${queue.size()}`);
